const body = $input.item.json.body || $input.item.json;
const title = body.title || 'Cinematic Epic Fight';
const characters = body.characters || '@hero (warrior in dark battle armor), @monster (4m crystal blade creature)';
const atmosphere = body.atmosphere || 'Grimdark, 20m fog visibility, cinematic anamorphic lighting';

// 3-Shot (30s) Seedance 2.5 Prompt Architecture
const shot1 = `[SHOT 1 | 00:00-00:10 | 50mm Lens Setup]\nAssets: ${characters}, Environment: ${atmosphere}\nCamera: 8m distance, dollies forward in straight line to 3m height, slowing down at 07.0s.\nTimecode: 0.0s-3.0s: Character reveals stance, snow particles lift from boots. 3.0s-7.5s: Energy core glows cyan, weapon unsheathes with metallic scrape. 7.5s-10.0s: Locks into battle ready posture for match cut.`;

const shot2 = `[SHOT 2 | 00:10-00:20 | 24mm Low-Angle Escalation]\nMatch Cut: Poses at 00:10.0 exactly match end of Shot 1.\nCamera: 180-degree low-angle arc orbiting from 3m to 1.5m radius.\nTimecode: 0.0s-2.0s: Forward sprint sprint 3x faster than standard dolly. 2.0s-6.0s: 0.2x Bullet-time dilation, blade gap narrows from 50cm to 5cm. 6.0s-10.0s: Normal time returns, crystal blade shatters enemy steel with real sparks and shockwave.`;

const shot3 = `[SHOT 3 | 00:20-00:30 | 85mm Telephoto to 35mm Wide Heroic Finish]\nCamera: Starts on 85mm eye close-up, hard snap zoom-out at 05.0s to 35mm wide frame.\nTimecode: 0.0s-4.5s: Intense facial reflection, breath vapor in cold air. 4.5s-5.0s: 0.5s instant snap weapon transformation. 5.0s-10.0s: Wide frame reveals entire army freezing in fog, eyes glowing red cliffhanger.`;

return {
  json: {
    projectId: 'VR-' + Date.now(),
    title: title,
    shots: [
      { shotNumber: 1, duration: 10, prompt: shot1 },
      { shotNumber: 2, duration: 10, prompt: shot2 },
      { shotNumber: 3, duration: 10, prompt: shot3 }
    ],
    totalDuration: 30,
    model: 'seedance-2.5',
    aspectRatio: '16:9'
  }
};
